/*
 * Gary-UI token projector.
 *
 * Reads the single source of truth ../../tokens/tokens.json and projects it into:
 *   1. tokens/base.css  — a delimited, auto-generated region of `--gary-*` CSS
 *      variables (dark on :root, light on `.light`, density overrides).
 *   2. src/lib/tokens.ts — a typed `garyTokens` const (as const) for consumers.
 *
 * Idempotent: hand-written content outside the BEGIN/END markers in base.css is
 * preserved; the TS file is regenerated in full (it has no hand-written part).
 *
 * Usage:  node scripts/generate-tokens.mjs   (npm run tokens:generate)
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const ADAPTER_ROOT = resolve(SCRIPT_DIR, "..");
const REPO_ROOT = resolve(ADAPTER_ROOT, "..", "..");

const TOKENS_JSON = join(REPO_ROOT, "tokens", "tokens.json");
const BASE_CSS = join(REPO_ROOT, "tokens", "base.css");
const TOKENS_TS = join(ADAPTER_ROOT, "src", "lib", "tokens.ts");

const BEGIN_MARK = "/*! gary-tokens:start — AUTO-GENERATED";
const END_MARK = "/*! gary-tokens:end */";
const BEGIN_LINE = `${BEGIN_MARK} by scripts/generate-tokens.mjs. Edit tokens.json, not this block. */`;
const END_LINE = END_MARK;

const TS_BANNER = `/*
 * AUTO-GENERATED by scripts/generate-tokens.mjs from ../../tokens/tokens.json.
 * Do not edit by hand — run \`npm run tokens:generate\` after changing tokens.json.
 */`;

/** Classify a token entry by which key shape it uses. */
function classify(entry) {
  if ("dark" in entry && "light" in entry) return "mode";
  if ("spacious" in entry && "balanced" in entry && "compact" in entry) return "density";
  if ("value" in entry) return "stable";
  return "unknown";
}

function cssLine(name, value) {
  return `  ${name}: ${value};`;
}

/** Build the auto-generated CSS region text. */
function buildCssRegion(tokens) {
  const root = []; // :root / dark / balanced
  const light = []; // .light overrides
  const spacious = [];
  const compact = [];

  for (const [name, entry] of Object.entries(tokens)) {
    const kind = classify(entry);
    if (kind === "mode") {
      root.push(cssLine(name, entry.dark));
      light.push(cssLine(name, entry.light));
    } else if (kind === "density") {
      root.push(cssLine(name, entry.balanced));
      spacious.push(cssLine(name, entry.spacious));
      compact.push(cssLine(name, entry.compact));
    } else if (kind === "stable") {
      root.push(cssLine(name, entry.value));
    } else {
      throw new Error(`generate-tokens: cannot classify token ${name}: ${JSON.stringify(entry)}`);
    }
  }

  const block = (selectors, bodyLines, extra = "") =>
    `${selectors} {\n${extra ? `  ${extra}\n` : ""}${bodyLines.join("\n")}\n}`;

  const parts = [];
  parts.push(BEGIN_LINE);
  parts.push(block(":root,\n[data-gary-theme=\"dark\"]", root, "color-scheme: dark;"));
  parts.push(block(".light,\n[data-gary-theme=\"light\"]", light, "color-scheme: light;"));
  if (spacious.length) parts.push(block("[data-gary-density=\"spacious\"]", spacious));
  if (compact.length) parts.push(block("[data-gary-density=\"compact\"]", compact));
  parts.push(END_LINE);
  return parts.join("\n");
}

/** Insert or replace the generated region inside base.css. */
function projectBaseCss(region) {
  const css = readFileSync(BASE_CSS, "utf8");
  const beginIdx = css.indexOf(BEGIN_MARK);
  const endIdx = css.indexOf(END_MARK);

  let next;
  if (beginIdx !== -1 && endIdx !== -1 && endIdx > beginIdx) {
    const before = css.slice(0, beginIdx);
    const after = css.slice(endIdx + END_MARK.length);
    next = before + region + after;
  } else {
    // No markers yet: insert the region right after the header comment block,
    // before the first rule. We anchor on the "@import" line.
    const importEnd = css.indexOf("\n", css.indexOf("@import"));
    if (importEnd === -1) throw new Error("generate-tokens: could not anchor insertion in base.css");
    next = css.slice(0, importEnd + 1) + "\n" + region + "\n" + css.slice(importEnd + 1);
  }
  writeFileSync(BASE_CSS, next, "utf8");
}

/** Build and write src/lib/tokens.ts. */
function projectTokensTs(tokens) {
  const body = Object.entries(tokens)
    .map(([name, entry]) => `  ${JSON.stringify(name)}: ${JSON.stringify(entry)},`)
    .join("\n");
  const content = `${TS_BANNER}
export const garyTokens = {
${body}
} as const;

export type GaryTokenName = keyof typeof garyTokens;
`;
  writeFileSync(TOKENS_TS, content, "utf8");
}

function main() {
  const data = JSON.parse(readFileSync(TOKENS_JSON, "utf8"));
  const tokens = data.tokens;

  const region = buildCssRegion(tokens);
  projectBaseCss(region);
  projectTokensTs(tokens);

  const modeCount = Object.values(tokens).filter((e) => classify(e) === "mode").length;
  const stableCount = Object.values(tokens).filter((e) => classify(e) === "stable").length;
  const densityCount = Object.values(tokens).filter((e) => classify(e) === "density").length;
  console.log(
    `generate-tokens: wrote base.css region (${modeCount} mode, ${stableCount} stable, ${densityCount} density tokens) and src/lib/tokens.ts`
  );
}

main();
